const j = $input.first().json;

// Gmail can return headers in different locations/formats
let headers = [];

if (Array.isArray(j.payload?.headers)) {
  headers = j.payload.headers;
} else if (Array.isArray(j.headers)) {
  headers = j.headers;
}

// Safely get a Gmail header
function getHeader(name) {
  const header = headers.find(
    h => String(h?.name || '').toLowerCase() === name.toLowerCase()
  );

  return header?.value || '';
}

// Get sender
let from =
  getHeader('From') ||
  j.from?.email ||
  j.from?.address ||
  j.sender?.email ||
  '';

from = String(from).trim();

// Extract email from:
// John Doe <john@example.com>
const emailMatch = from.match(/<([^>]+)>/);

const customerEmail = (
  emailMatch ? emailMatch[1] : from
).trim().toLowerCase();

// Get message body from the different possible Gmail fields
const body =
  j.textPlain ||
  j.text ||
  j.body?.text ||
  j.snippet ||
  '';

// Get subject
const subject =
  getHeader('Subject') ||
  j.subject ||
  '';

// Return normalized data
return [
  {
    json: {
      message_id: j.id || null,
      thread_id: j.threadId || null,
      customer_email: customerEmail,
      subject: String(subject).trim(),
      body: String(body).trim(),
      received_at: new Date().toISOString()
    }
  }
];
